# Generated by manage.py generate_test_cases.
from django.core.exceptions import ValidationError
from django.test import override_settings

from bloomerp.config.definition import BloomerpConfig
from bloomerp.form_fields.booking_location_field import BookingLocationField
from bloomerp.tests.base import (
    BloomerpFormFieldTestCase,
    ExpectedFormFieldException,
    FormFieldScenario,
)
from bloomerp.tests.communication.conferencing.test_configuration import (
    conferencing_config,
)
from bloomerp.widgets.booking_location_widget import CREATE_BOOKING_CONFERENCE


class TestBookingLocationFieldFormField(BloomerpFormFieldTestCase):
    field_class = BookingLocationField

    def get_test_scenarios(self) -> list[FormFieldScenario[BookingLocationField]]:
        """Accept ordinary locations and require configuration for generated meetings."""
        return [
            FormFieldScenario(
                name="Clean an address",
                clean_value=" Room 4 ",
                clean_result_validators=self.is_address,
            ),
            FormFieldScenario(
                name="Reject automatic meetings when conferencing is disabled",
                preparation=self.disable_conferencing,
                clean_value=CREATE_BOOKING_CONFERENCE,
                expected_exceptions=[
                    ExpectedFormFieldException(phase="clean", exception=ValidationError),
                ],
            ),
            FormFieldScenario(
                name="Retain the automatic meeting selection when enabled",
                preparation=self.enable_conferencing,
                clean_value=CREATE_BOOKING_CONFERENCE,
                clean_result_validators=self.is_meeting,
            ),
        ]

    def disable_conferencing(self) -> None:
        """Set an explicit disabled configuration for the validator."""
        self.enterContext(override_settings(BLOOMERP_CONFIG=BloomerpConfig()))

    def enable_conferencing(self) -> None:
        """Provide the same configuration used by the conference route tests."""
        self.enterContext(override_settings(BLOOMERP_CONFIG=conferencing_config()))

    def is_address(self, value: str) -> bool:
        """Check the cleaned non-conference value."""
        return value == "Room 4"

    def is_meeting(self, value: str) -> bool:
        """Preserve the automatic location setting for later confirmation."""
        return value == CREATE_BOOKING_CONFERENCE
